script.on_init(function()
 local name='tech-priests-emergency-power-grid';local p=assert(prototypes.entity[name]);local f=game.forces.player;local s=game.surfaces[1];s.request_to_generate_chunks({20,20},1);s.force_generate_chunk_requests();local tiles={};for x=10,40 do for y=10,40 do tiles[#tiles+1]={name='grass-1',position={x,y}}end end;s.set_tiles(tiles,true)
 for _,e in pairs(s.find_entities_filtered{area={{10,10},{40,40}},type={'tree','simple-entity','cliff'}})do e.destroy()end
 local e=assert(s.create_entity{name=name,position={20.5,20.5},force=f});local dirs={};for _,d in ipairs({0,4,8,12})do e.direction=d;dirs[#dirs+1]={requested=d,actual=e.direction,rotate=e.rotate(),can_place=s.can_place_entity{name=name,position={32.5,20.5},direction=d,force=f}}end;e.direction=0
 local wires={};for id,c in pairs(e.get_wire_connectors(true)or{})do wires[#wires+1]={id=id,real_connections=c.real_connection_count}end
 local unlocks={};for n,t in pairs(prototypes.technology)do for _,ef in pairs(t.effects or{})do if ef.type=='unlock-recipe'and ef.recipe==name then unlocks[#unlocks+1]=n end end end
 local item=prototypes.item[name];local r=prototypes.recipe[name];local report={entity={name=name,type=p.type,footprint={p.tile_width,p.tile_height},collision_box=p.collision_box,selection_box=p.selection_box,max_health=p.get_max_health(),supply_area_radius=p.get_supply_area_distance(),copper_wire_reach=p.get_max_wire_distance(),circuit_wire_reach=p.get_max_circuit_wire_distance(),auto_connect_up_to_n_wires=p.auto_connect_up_to_n_wires,burner=not not e.burner,fluid_storage_count=e.fluids_count,wire_connectors=wires,initial_isolated_electric_network_id=e.electric_network_id,surface_conditions=p.surface_conditions},item={name=name,place_result=item.place_result.name,stack_size=item.stack_size,weight=item.weight},building_recipe={enabled=f.recipes[name].enabled,seconds=r.energy,categories=r.categories,ingredients=r.ingredients,products=r.products},processing_recipes={},building_unlocks=unlocks,native_directions=dirs,normal_nauvis_placement=dirs[1].can_place,prototype_overrides=false}
 helpers.write_file('power-grid-contract/contract.json',helpers.table_to_json(report),false);log('POWER_GRID_ACTUAL_CONTRACT_CAPTURED')
end)
